export class MemberSuspendedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly userId: UserId) {
    super(`Member ${userId} is suspended`);
    this.name = "MemberSuspendedError";
  }
}

/** Throws `MemberSuspendedError` when `userId` is a suspended member of the org. */
export async function assertAssignable(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member?.status === "suspended") throw new MemberSuspendedError(userId);
}

type SuspensionInput = { orgId: OrgId; memberId: MemberId };

/** Shared guards for suspend / reinstate: scope, existence, permission, rank. */
async function loadSuspensionTarget(
  actor: Actor,
  input: SuspensionInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = await memberRepo.findMemberById(input.orgId, input.memberId);
  if (!member || member.archivedAt !== null) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error("You cannot suspend or reinstate yourself");
  }
  if (ROLE_RANK[member.role] > ROLE_RANK[actor.role]) {
    throw new Error(`A ${actor.role} cannot suspend or reinstate a ${member.role}`);
  }
  return member;
}

/** Locks a member out without removing them; they keep role and seat. */
export async function suspendMember(
  actor: Actor,
  input: SuspensionInput,
): Promise<Member> {
  const member = await loadSuspensionTarget(actor, input);
  if (member.status === "suspended") return member;

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const updated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

/** Lifts a suspension. */
export async function reinstateMember(
  actor: Actor,
  input: SuspensionInput,
): Promise<Member> {
  const member = await loadSuspensionTarget(actor, input);
  if (member.status !== "suspended") return member;

  const updated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

